Rules.InvariantScript:
Set(
    varNewIncidentID,
    "INC-" & Text(Now(), "yyyymmddhhmmss")
);

Patch(
    'List 1: Incidents',
    Defaults('List 1: Incidents'),
    {
        Title: varNewIncidentID,
        IncidentID: varNewIncidentID,
        IncidentType: {Value: "Fire"},
        Description: TextInput2.Text,
        Severity: {Value: drpFireSeverity.Selected.Value},
        Latitude: Location.Latitude,
        Longitude: Location.Longitude,
        LocationText: TextInput2_1.Text,
        SubmittedTime: Now(),
        Status: {Value: "New"},
        SubmittedByEmail: User().Email
    }
);

Set(varLastSubmissionType, "Fire Alert");

Set(varSubmittedTime, Now());

Navigate(ConfirmationScreen, ScreenTransition.Fade)
